    color: var(--text);
    height: 100vh;
    display: flex;
    flex-direction: column;
  }
  header {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 10px 16px;
    background: var(--panel);
    border-bottom: 1px solid var(--border);
  }
  header h1 {
    font-size: 18px;
    margin: 0;
    letter-spacing: 0.5px;
  }
  header h1 span { color: var(--accent); }
  .spacer { flex: 1; }
  .toolbar { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }

  button, select, input[type="number"] {
    background: var(--panel2);
    color: var(--text);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 6px 10px;
    font-size: 13px;
    cursor: pointer;
    transition: background .12s, border-color .12s;
  }
  button:hover { background: #36363f; border-color: #4a4a56; }
  button:active { transform: translateY(1px); }
  button:disabled { opacity: .4; cursor: default; }
  button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
  button.primary:hover { background: #7d8aff; }

  .seg { display: flex; border: 1px solid var(--border); border-radius: 6px; overflow: hidden; }
  .seg button { border: none; border-radius: 0; background: transparent; }
  .seg button.active { background: var(--accent); color: #fff; }

  .field { display: flex; align-items: center; gap: 6px; color: var(--muted); font-size: 13px; }
  .field input[type="number"] { width: 64px; }

  main {
    flex: 1;
    display: flex;
    overflow: hidden;
  }
  #stage {
    flex: 1;
    overflow: auto;
    display: flex;
    align-items: center;
    justify-content: center;
